  "Allow the microphone when your browser asks.": { es: "Permite el micrófono cuando el navegador lo pida.", ar: "اسمح باستخدام الميكروفون عندما يطلب المتصفح ذلك.", zh: "浏览器询问时，请允许使用麦克风。", sw: "Ruhusu maikrofoni kivinjari chako kinapouliza.", sv: "Tillåt mikrofonen när webbläsaren frågar.", de: "Erlaube das Mikrofon, wenn dein Browser fragt.", pt: "Permita o microfone quando o navegador pedir.", fr: "Autorisez le micro quand votre navigateur le demande." },
  "Listening… {mic}": { es: "Escuchando… {mic}", ar: "جارٍ الاستماع… {mic}", zh: "正在聆听… {mic}", sw: "Inasikiliza… {mic}", sv: "Lyssnar… {mic}", de: "Hört zu… {mic}", pt: "Ouvindo… {mic}", fr: "Écoute… {mic}" },
  "Microphone off.": { es: "Micrófono apagado.", ar: "الميكروفون متوقف.", zh: "麦克风已关闭。", sw: "Maikrofoni imezimwa.", sv: "Mikrofonen är av.", de: "Mikrofon aus.", pt: "Microfone desligado.", fr: "Micro coupé." },
  "Demo: a string being tuned up — no microphone used.": { es: "Demostración: una cuerda que se va afinando, sin usar el micrófono.", ar: "عرض تجريبي: وتر يُضبط تدريجيًا — دون استخدام الميكروفون.", zh: "演示：一根正在被调准的琴弦——不使用麦克风。", sw: "Maonyesho: uzi unaotuniwa hatua kwa hatua — bila kutumia maikrofoni.", sv: "Demo: en sträng som stäms upp — ingen mikrofon används.", de: "Demo: Eine Saite wird hochgestimmt — ohne Mikrofon.", pt: "Demonstração: uma corda sendo afinada — sem usar o microfone.", fr: "Démo : une corde qu’on accorde — sans micro." },
  "Demo stopped.": { es: "Demostración detenida.", ar: "توقف العرض التجريبي.", zh: "演示已停止。", sw: "Maonyesho yamesimama.", sv: "Demon stoppad.", de: "Demo gestoppt.", pt: "Demonstração parada.", fr: "Démo arrêtée." },
  "The microphone is blocked. Allow it from the icon in the address bar, or try the demo sound.": { es: "El micrófono está bloqueado. Permítelo desde el icono de la barra de direcciones o prueba el sonido de demostración.", ar: "الميكروفون محظور. اسمح به من الأيقونة في شريط العنوان، أو جرّب الصوت التجريبي.", zh: "麦克风被阻止了。请通过地址栏中的图标允许它，或试试演示声音。", sw: "Maikrofoni imezuiwa. Iruhusu kupitia ikoni kwenye upau wa anwani, au jaribu sauti ya maonyesho.", sv: "Mikrofonen är blockerad. Tillåt den via ikonen i adressfältet, eller prova demoljudet.", de: "Das Mikrofon ist blockiert. Erlaube es über das Symbol in der Adressleiste oder probiere den Demoklang.", pt: "O microfone está bloqueado. Permita-o pelo ícone na barra de endereço ou experimente o som de demonstração.", fr: "Le micro est bloqué. Autorisez-le via l’icône de la barre d’adresse, ou essayez le son de démo." },
  "No microphone found ({err}). Try the demo sound.": { es: "No se encontró ningún micrófono ({err}). Prueba el sonido de demostración.", ar: "لم يُعثر على ميكروفون ({err}). جرّب الصوت التجريبي.", zh: "未找到麦克风（{err}）。试试演示声音。", sw: "Hakuna maikrofoni iliyopatikana ({err}). Jaribu sauti ya maonyesho.", sv: "Ingen mikrofon hittades ({err}). Prova demoljudet.", de: "Kein Mikrofon gefunden ({err}). Probiere den Demoklang.", pt: "Nenhum microfone encontrado ({err}). Experimente o som de demonstração.", fr: "Aucun micro trouvé ({err}). Essayez le son de démo." },
  "This browser cannot use the microphone here. Try the demo sound, or open the page over https in Chrome, Edge, Firefox or Safari.": { es: "Este navegador no puede usar el micrófono aquí. Prueba el sonido de demostración o abre la página con https en Chrome, Edge, Firefox o Safari.", ar: "لا يستطيع هذا المتصفح استخدام الميكروفون هنا. جرّب الصوت التجريبي، أو افتح الصفحة عبر https في Chrome أو Edge أو Firefox أو Safari.", zh: "此浏览器无法在这里使用麦克风。试试演示声音，或在 Chrome、Edge、Firefox 或 Safari 中通过 https 打开此页面。", sw: "Kivinjari hiki hakiwezi kutumia maikrofoni hapa. Jaribu sauti ya maonyesho, au fungua ukurasa kupitia https katika Chrome, Edge, Firefox au Safari.", sv: "Den här webbläsaren kan inte använda mikrofonen här. Prova demoljudet, eller öppna sidan via https i Chrome, Edge, Firefox eller Safari.", de: "Dieser Browser kann das Mikrofon hier nicht nutzen. Probiere den Demoklang oder öffne die Seite über https in Chrome, Edge, Firefox oder Safari.", pt: "Este navegador não pode usar o microfone aqui. Experimente o som de demonstração ou abra a página por https no Chrome, Edge, Firefox ou Safari.", fr: "Ce navigateur ne peut pas utiliser le micro ici. Essayez le son de démo, ou ouvrez la page en https dans Chrome, Edge, Firefox ou Safari." },
