  "⬆ Much too low — tighten": { es: "⬆ Demasiado bajo: tensa la cuerda", ar: "⬆ منخفض جدًا — شُدّ الوتر", zh: "⬆ 太低了——拧紧", sw: "⬆ Chini mno — kaza", sv: "⬆ Alldeles för lågt — spänn", de: "⬆ Viel zu tief — spannen", pt: "⬆ Baixo demais — aperte", fr: "⬆ Beaucoup trop bas — tendez" },
  "⬇ Much too high — loosen": { es: "⬇ Demasiado alto: afloja la cuerda", ar: "⬇ مرتفع جدًا — أرخِ الوتر", zh: "⬇ 太高了——放松", sw: "⬇ Juu mno — legeza", sv: "⬇ Alldeles för högt — slacka", de: "⬇ Viel zu hoch — lockern", pt: "⬇ Alto demais — afrouxe", fr: "⬇ Beaucoup trop haut — détendez" },
  "⬆ Too low — tune up": { es: "⬆ Bajo: sube la afinación", ar: "⬆ منخفض — ارفع الطبقة", zh: "⬆ 偏低——调高", sw: "⬆ Chini — panda juu", sv: "⬆ För lågt — stäm upp", de: "⬆ Zu tief — höher stimmen", pt: "⬆ Baixo — suba a afinação", fr: "⬆ Trop bas — montez" },
  "⬇ Too high — tune down": { es: "⬇ Alto: baja la afinación", ar: "⬇ مرتفع — اخفض الطبقة", zh: "⬇ 偏高——调低", sw: "⬇ Juu — shuka chini", sv: "⬇ För högt — stäm ner", de: "⬇ Zu hoch — tiefer stimmen", pt: "⬇ Alto — desça a afinação", fr: "⬇ Trop haut — descendez" },
  "Start the microphone, then pluck one string and let it ring.": { es: "Activa el micrófono, pulsa una cuerda y déjala sonar.", ar: "شغّل الميكروفون، ثم انقر وترًا واحدًا واتركه يرنّ.", zh: "打开麦克风，然后拨一根弦，让它持续发声。", sw: "Washa maikrofoni, kisha chapa uzi mmoja na uuache ulie.", sv: "Starta mikrofonen, knäpp på en sträng och låt den klinga.", de: "Starte das Mikrofon, zupfe eine Saite und lass sie klingen.", pt: "Ligue o microfone, toque uma corda e deixe-a soar.", fr: "Activez le micro, pincez une corde et laissez-la sonner." },
  "Heard {heard} · target {target} ({hz} Hz), string {n}": { es: "Se oye {heard} · objetivo {target} ({hz} Hz), cuerda {n}", ar: "المسموع {heard} · الهدف {target} ({hz} هرتز)، الوتر {n}", zh: "听到 {heard} · 目标 {target}（{hz} Hz），第 {n} 弦", sw: "Imesikika {heard} · lengo {target} ({hz} Hz), uzi {n}", sv: "Hörd {heard} · mål {target} ({hz} Hz), sträng {n}", de: "Gehört {heard} · Ziel {target} ({hz} Hz), Saite {n}", pt: "Ouvido {heard} · alvo {target} ({hz} Hz), corda {n}", fr: "Entendu {heard} · cible {target} ({hz} Hz), corde {n}" },
  "Heard {heard} · target {target} ({hz} Hz), string {n} (locked)": { es: "Se oye {heard} · objetivo {target} ({hz} Hz), cuerda {n} (fijada)", ar: "المسموع {heard} · الهدف {target} ({hz} هرتز)، الوتر {n} (مثبّت)", zh: "听到 {heard} · 目标 {target}（{hz} Hz），第 {n} 弦（已锁定）", sw: "Imesikika {heard} · lengo {target} ({hz} Hz), uzi {n} (umefungwa)", sv: "Hörd {heard} · mål {target} ({hz} Hz), sträng {n} (låst)", de: "Gehört {heard} · Ziel {target} ({hz} Hz), Saite {n} (fest)", pt: "Ouvido {heard} · alvo {target} ({hz} Hz), corda {n} (fixada)", fr: "Entendu {heard} · cible {target} ({hz} Hz), corde {n} (verrouillée)" },
  "Target {hz} Hz at A4 = {a4} Hz": { es: "Objetivo {hz} Hz con A4 = {a4} Hz", ar: "الهدف {hz} هرتز عند A4 = {a4} هرتز", zh: "目标 {hz} Hz（A4 = {a4} Hz）", sw: "Lengo {hz} Hz kwa A4 = {a4} Hz", sv: "Mål {hz} Hz vid A4 = {a4} Hz", de: "Ziel {hz} Hz bei A4 = {a4} Hz", pt: "Alvo {hz} Hz com A4 = {a4} Hz", fr: "Cible {hz} Hz avec A4 = {a4} Hz" },
  "Strings: press one to hear it and tune only that string": { es: "Cuerdas: pulsa una para oírla y afinar solo esa cuerda", ar: "الأوتار: اضغط على وتر لتسمعه وتضبطه وحده", zh: "琴弦：点一根弦可以听它的音，并只调这根弦", sw: "Nyuzi: bonyeza mmoja kuusikia na kutuni uzi huo tu", sv: "Strängar: tryck på en för att höra den och stämma bara den", de: "Saiten: Tippe eine an, um sie zu hören und nur sie zu stimmen", pt: "Cordas: toque em uma para ouvi-la e afinar só essa corda", fr: "Cordes : appuyez sur une corde pour l’entendre et n’accorder qu’elle" },
  "string {n}": { es: "cuerda {n}", ar: "الوتر {n}", zh: "第 {n} 弦", sw: "uzi {n}", sv: "sträng {n}", de: "Saite {n}", pt: "corda {n}", fr: "corde {n}" },
  "Find the string automatically": { es: "Detectar la cuerda automáticamente", ar: "اكتشف الوتر تلقائيًا", zh: "自动识别琴弦", sw: "Tambua uzi kiotomatiki", sv: "Hitta strängen automatiskt", de: "Saite automatisch erkennen", pt: "Encontrar a corda automaticamente", fr: "Trouver la corde automatiquement" },
  "Play the string when I press it": { es: "Tocar la cuerda cuando la pulse", ar: "اعزف الوتر عندما أضغط عليه", zh: "点按琴弦时播放它的音", sw: "Cheza uzi ninapoubonyeza", sv: "Spela strängen när jag trycker på den", de: "Saite abspielen, wenn ich sie antippe", pt: "Tocar a corda quando eu tocar nela", fr: "Jouer la corde quand j’appuie dessus" },
  "Pitch over the last seconds: the middle line is in tune": { es: "Altura en los últimos segundos: la línea central es la afinación correcta", ar: "طبقة الصوت في الثواني الأخيرة: الخط الأوسط هو الضبط الصحيح", zh: "最近几秒的音高：中线表示音准", sw: "Kiwango cha sauti sekunde za mwisho: mstari wa katikati ni sawa", sv: "Tonhöjd de senaste sekunderna: mittlinjen är rent", de: "Tonhöhe der letzten Sekunden: Die Mittellinie ist gestimmt", pt: "Altura nos últimos segundos: a linha do meio é afinado", fr: "Hauteur des dernières secondes : la ligne du milieu est juste" },
  "Pitch over time: the middle line is in tune, the green band is ±5 cents. A steady line means a steady note.": { es: "Altura a lo largo del tiempo: la línea central es la afinación correcta y la franja verde es ±5 cents. Una línea estable significa una nota estable.", ar: "طبقة الصوت عبر الزمن: الخط الأوسط هو الضبط الصحيح، والشريط الأخضر ±5 سنت. الخط الثابت يعني نغمة ثابتة.", zh: "音高随时间变化：中线表示音准，绿色带为 ±5 音分。线越平稳，音越稳。", sw: "Kiwango cha sauti kwa muda: mstari wa katikati ni sawa, ukanda wa kijani ni ±5 senti. Mstari thabiti unamaanisha noti thabiti.", sv: "Tonhöjd över tid: mittlinjen är rent, det gröna bandet är ±5 cent. En jämn linje betyder en stadig ton.", de: "Tonhöhe über die Zeit: Die Mittellinie ist gestimmt, das grüne Band ±5 Cent. Eine ruhige Linie bedeutet einen ruhigen Ton.", pt: "Altura ao longo do tempo: a linha do meio é afinado e a faixa verde é ±5 cents. Uma linha estável significa uma nota estável.", fr: "Hauteur dans le temps : la ligne du milieu est juste, la bande verte fait ±5 cents. Une ligne stable signifie une note stable." },
  "BPM": { es: "BPM", ar: "نبضة/د", zh: "BPM", sw: "BPM", sv: "BPM", de: "BPM", pt: "BPM", fr: "BPM" },
  "Grave — very slow": { es: "Grave: muy lento", ar: "غراف — بطيء جدًا", zh: "Grave — 极慢", sw: "Grave — polepole sana", sv: "Grave — mycket långsamt", de: "Grave — sehr langsam", pt: "Grave — muito lento", fr: "Grave — très lent" },
